installer-gui-script.script:
function etphCheck() {
  if (system.compareVersions(system.version.ProductVersion, '@MIN_MACOS@') < 0) {
    my.result.type = 'Fatal';
    my.result.title = 'macOS @MIN_MACOS@ or newer required';
    my.result.message = 'ETPH needs macOS @MIN_MACOS@ or newer on a Mac with Apple silicon. This Mac runs macOS ' + system.version.ProductVersion + '.';
    return false;
  }
  return true;
}
